ys.path.insert(0, \".\")\nfrom src.bookings import bookings_conflict\n\n# The reported bug: A checks out the morning B checks in.\nassert not bookings_conflict(\"2026-03-05\", \"2026-03-10\", \"2026-03-10\", \"2026-03-12\"), \\\n    \"checkout day is exclusive; these must not conflict\"\n# Same boundary with the arguments swapped -- catches a one-sided fix.\nassert not bookings_conflict(\"2026-03-10\", \"2026-03-12\", \"2026-03-05\", \"2026-03-10\"), \\\n    \"boundary must hold with arguments swapped\"\n\n# Genuine overlaps must still be detected.\nassert bookings_conflict(\"2026-03-05\", \"2026-03-10\", \"2026-03-08\", \"2026-03-12\")\nassert bookings_conflict(\"2026-03-08\", \"2026-03-12\", \"2026-03-05\", \"2026-03-10\")\nassert bookings_conflict(\"2026-03-05\", \"2026-03-10\", \"2026-03-05\", \"2026-03-10\"), \\\n    \"identical ranges overlap\"\nassert bookings_conflict(\"2026-03-01\", \"2026-03-31\", \"2026-03-10\", \"2026-03-12\"), \\\n    \"fully contained range overlaps\"\n\n# Disjoint ranges must not conflict.\nassert not bookings_conflict(\"2026-03-01\", \"2026-03-05\", \"2026-03-20\", \"2026-03-25\")\n\nprint(\"BOOKINGS_OK\")\n"}],"isError":false,"timestamp":1787897246961}]}
